#include <linux/bitmap.h>
#include <linux/uaccess.h>
#include <linux/compat.h>

int compat_sys_mempolicy(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode)
{
    int err;
    unsigned long *bitmap = NULL;
    unsigned int bits = 0;
    unsigned int size = 0;

    if (maxnode) {
        bits = maxnode;
        size = BITS_TO_LONGS(bits) * sizeof(long);
        bitmap = compat_alloc_user_space(size);
        if (!access_ok(VERIFY_READ, nmask, size)) {
            return -EFAULT;
        }
        if (copy_from_user(bitmap, nmask, size)) {
            return -EFAULT;
        }
    }

    err = sys_mempolicy(mode, bitmap, maxnode);

    if (nmask && maxnode) {
        if (copy_to_user(nmask, bitmap, size)) {
            return -EFAULT;
        }
    }

    return err;
}

