asmlinkage long sys_compat_mempolicy_set(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode)
{
	DECLARE_BITMAP(bitmap, MAX_NUMNODES);
	unsigned long nbits = maxnode;
	unsigned long size = BITMAP_SIZE(nbits);
	int err = 0;

	if (nmask) {
		if (maxnode > MAX_NUMNODES)
			maxnode = MAX_NUMNODES;
		if (copy_from_user(bitmap, nmask, (size_t) ((maxnode + 7) / 8)))
			return -EFAULT;
	}

	err = do_set_mempolicy(mode, bitmap, nbits);

	if (!err && nmask) {
		if (copy_to_user(nmask, bitmap, (size_t) ((maxnode + 7) / 8)))
			return -EFAULT;
	}

	return err;
}

