SYSCALL_DEFINE3(set_mempolicy_compat, int, mode, compat_ulong_t __user *, nmask,
                compat_ulong_t, maxnode)
{
    int err = 0;
    unsigned long *bmp = NULL;
    unsigned int nbits = maxnode;
    unsigned int size = ALIGN(nbits, 8 * sizeof(long)) / (8 * sizeof(long));

    if (nmask) {
        bmp = compat_alloc_user_space(size * sizeof(long));
        if (!bmp)
            return -EFAULT;

        if (copy_from_user(bmp, nmask, size * sizeof(compat_ulong_t))) {
            err = -EFAULT;
            goto out;
        }
    }

    err = sys_set_mempolicy(mode, bmp, nbits);

