#include <linux/syscalls.h>
#include <linux/uaccess.h>
#include <linux/bitmap.h>

SYSCALL_DEFINE3(set_mempolicy_compat, int, mode, compat_ulong_t __user *, nmask, compat_ulong_t, maxnode)
{
    unsigned long *bmp = NULL;
    int nbits = 0;
    int ret = 0;

    if (maxnode == 0)
        return -EINVAL;

    nbits = fls(maxnode);
    if (nbits <= 0)
        return -EINVAL;

    if (nmask) {
        bmp = kmalloc(BITS_TO_LONGS(nbits) * sizeof(unsigned long), GFP_KERNEL);
        if (!bmp)
            return -ENOMEM;

        if (copy_from_user(bmp, nmask, (nbits + 7) / 8)) {
            ret = -EFAULT;
            goto out_free;
        }
    }

    ret = sys_set_mempolicy(mode, bmp, nbits);

    if (nmask && copy_to_user(nmask, bmp, (nbits + 7) / 8))
        ret = -EFAULT;

out_free:
    kfree(bmp);
    return ret;
}

