SYSCALL_DEFINE3(set_mempolicy_compat, int, mode, compat_ulong_t __user *, nmask, compat_ulong_t, maxnode)
{
    unsigned long *bitmap = NULL;
    unsigned long nbits;
    int ret = -EINVAL;

    if (maxnode == 0)
        return -EINVAL;

    nbits = maxnode;
    if (nmask) {
        bitmap = kmalloc(BITS_TO_LONGS(nbits) * sizeof(unsigned long), GFP_KERNEL);
        if (!bitmap)
            return -ENOMEM;

        if (copy_from_user(bitmap, nmask, COMPAT_BITS_TO_LONGS(nbits) * sizeof(compat_ulong_t)))
            goto out_free;
    }

    ret = sys_set_mempolicy(mode, bitmap, nbits);
    if (ret >= 0 && nmask && copy_to_user(nmask, bitmap, COMPAT_BITS_TO_LONGS(nbits) * sizeof(compat_ulong_t)))
